{
  "PROP-legion-backe-pre-004": {
    "property_id": "PROP-legion-backe-pre-004",
    "audit_result": {
      "property_id": "PROP-legion-backe-pre-004",
      "classification": "potential-vulnerability",
      "code_path": "src/sales/LegionAbstractSale.sol::claimTokenAllocation::L251-313",
      "proof_trace": "The `claimTokenAllocation` in `LegionAbstractSale` applies `whenSaleResultsArePublished` (checks `totalTokensAllocated != 0`) but not `whenTokensSupplied`; neither the function body nor `_verifyCanClaimTokenAllocation` (L710-740) inspects `s_saleStatus.tokensSupplied`. For non-zero allocations, the missing guard is indirectly blocked by `safeTransfer` reverting when the contract holds no `askToken` balance, but this implicit enforcement fails if the contract receives a premature token balance (direct ERC20 send before `supplyTokens`) or if an investor has a zero-amount merkle entry (both transfer branches skipped, `hasSettled = true` persists). The inconsistency is confirmed by `LegionPreLiquidApprovedSale.claimTokenAllocation` (L409) which explicitly applies `whenTokensSupplied`.",
      "attack_scenario": "An investor calls `claimTokenAllocation` after sale results are published but before `supplyTokens` is called; if the project accidentally sends `askToken` directly to the contract first, the transfer succeeds, the investor receives tokens and `hasSettled` is permanently set \u2014 allowing early token drain while `tokensSupplied` remains false and potentially desynchronizing accounting.",
      "checklist_id": "PROP-legion-backe-pre-004"
    },
    "text": "claimTokenAllocation requires tokensSupplied == true before investor can claim.",
    "assertion": "pre(claimTokenAllocation()) => tokensSupplied == true",
    "covers": "SG-009",
    "severity": "HIGH",
    "type": "pre-condition"
  }
}

